            ['term' => 'Social Domain', 'definition' => 'Involves awareness of others thoughts and feelings, interpersonal empathy, communication abilities, friendship formation, and social judgment.'],
            ['term' => 'Practical Domain', 'definition' => 'Refers to personal life management, including personal hygiene, meal preparation, transportation, occupational duties, and financial navigation.'],
            ['term' => 'Adaptive Functioning', 'definition' => 'The collection of conceptual, social, and practical skills that individuals learn and perform in their daily lives to function independently.']
        ]
